async function upsertStatusComment(repository, issueNumber, body, dependencies, botLogin) {
  const comments = await dependencies.provider.listComments(
    repository,
    issueNumber
  );
  const existing = findDraftPrComment(comments, botLogin);
  if (existing) {
    await dependencies.provider.updateComment(
      repository,
      issueNumber,
      existing.id,
      body
    );
  } else {
    await dependencies.provider.createComment(repository, issueNumber, body);
  }
}
function selectContextComments(comments, botLogin) {
  const expectedBot = botLogin?.trim().toLowerCase();
  return comments.filter((comment) => {
    const managedBot = expectedBot && comment.user?.login.trim().toLowerCase() === expectedBot;
    return !(managedBot && (comment.body.startsWith(DRAFT_PR_COMMENT_PREFIX) || isIssueTriageComment(comment.body)));
  }).sort((left, right) => left.id - right.id).slice(-50).map((comment) => ({
    ...comment,
    body: truncateText(comment.body, 4e3)
  }));
}
function validateImplementedAnalysis(analysis, inspection) {
  if (!sanitizeTitle(analysis.prTitle)) {
    throw new Error("implemented result requires a Pull Request title");
  }
  if (inspection.changedFiles.length === 0) {
    throw new Error(
      "implemented result requires a non-empty repository change"
    );
  }
  if (!inspection.diffCheckPassed) {
    throw new Error("git diff --check rejected the repository change");
  }
  if (inspection.secretFindingPaths.length > 0) {
    throw new Error(
      `possible credential material detected in: ${inspection.secretFindingPaths.join(", ")}`
    );
  }
  if (analysis.validationOverride && !hasConsistentValidationOverride(analysis)) {
    throw new Error(
      "implemented result has an inconsistent validation override"
    );
  }
  if (analysis.tests.some((test) => test.status === "failed") && !hasConsistentValidationOverride(analysis)) {
    throw new Error("implemented result reports a failed validation command");
  }
}
function outcomeReasons(analysis) {
  return [
    ...analysis.risk.reasons,
    ...analysis.notes,
    ...analysis.summary
  ].slice(0, 8);
}
function failureReasons(analysis) {
  const validationFailures = analysis.tests.filter((test) => test.status === "failed" || test.status === "not_run").map((test) => {
    const prefix = test.status === "failed" ? "Validation failed" : "Validation not run";
    return `${prefix}: ${test.command}${test.details ? ` \u2014 ${test.details}` : ""}`;
  });
  return [
    ...validationFailures,
    ...analysis.risk.reasons,
    ...analysis.notes,
    ...analysis.summary
  ].slice(0, 8);
}
function buildPullRequestBody(issueNumber, analysis) {
  const lines = [`Closes #${issueNumber}`, "", "## Summary", ""];
  for (const item of analysis.summary) lines.push(`- ${sanitizeLine2(item)}`);
  lines.push("", "## Validation", "");
  if (analysis.tests.length === 0) {
    lines.push("- Not reported.");
  } else {
    for (const test of analysis.tests) {
      lines.push(
        `- \`${sanitizeCode(test.command)}\` \u2014 ${test.status}${test.details ? `: ${sanitizeLine2(test.details)}` : ""}`
      );
    }
  }
  if (analysis.validationOverride) {
    lines.push(
      "",
      "## Validation override",
      "",
      `- Classification: \`${analysis.validationOverride.classification}\``,
      `- Source: \`${analysis.validationOverride.source}\``,
      `- Reason: ${sanitizeLine2(analysis.validationOverride.reason)}`
    );
  }
  lines.push("", "## Risk", "", `- Level: \`${analysis.risk.level}\``);
  for (const reason of analysis.risk.reasons) {
    lines.push(`- ${sanitizeLine2(reason)}`);
  }
  if (analysis.notes.length > 0) {
    lines.push("", "## Notes", "");
    for (const note of analysis.notes) lines.push(`- ${sanitizeLine2(note)}`);
  }
  lines.push(
    "",
    "_Prepared by the repository development Agent and opened as a Draft Pull Request for maintainer review._"
  );
  return lines.join("\n");
}
function sanitizeLine2(value) {
  return value.replace(/<!--[\s\S]*?-->/g, "").replace(/[\r\n]+/g, " ").replace(/\s+/g, " ").trim().slice(0, 500);
}
function sanitizeCode(value) {
  return sanitizeLine2(value).replace(/`/g, "'");
}
function requiredBotLogin(value) {
  const normalized = value?.trim();
  if (!normalized)
    throw new Error("Draft PR bot login is required in apply mode");
  return normalized;
}

// src/draft-pr/main.ts
async function main() {
  const options = parseArguments(process.argv.slice(2));
  const apply = envBoolean(process.env.DRAFT_PR_APPLY);
  const allowedRepository = process.env.DRAFT_PR_ALLOWED_REPOSITORY?.trim() || process.env.GITHUB_ALLOWED_REPOSITORY?.trim() || "";
  if (["prepare", "inspect-validation", "apply", "fail"].includes(options.command)) {
    assertBoundDraftPrTarget(
      options.repository,
      options.issueNumber,
      apply,
      process.env
    );
  } else {
    assertBoundReviewTarget(
      options.repository,
      options.pullRequestNumber,
      apply,
      process.env
    );
  }
  if (options.command === "inspect-validation") {
    assertAllowedRepository(options.repository, allowedRepository);
    const result2 = await fingerprintDraftPrWorkspace(
      process.env.DRAFT_PR_WORKSPACE_ROOT?.trim() || "/draft-pr-workspaces",
      options.workspacePath
    );
    process.stdout.write(`${JSON.stringify(result2, null, 2)}
`);
    return;
  }
  const policy = await loadPolicy();
  const token = await resolveGitHubToken(options.repository);
  const provider = new GitHubClient({
    ...token ? { token } : {},
    ...process.env.GITHUB_API_URL ? { baseUrl: process.env.GITHUB_API_URL } : {}
  });
  const workspace = new GitDraftPrWorkspace({
    root: process.env.DRAFT_PR_WORKSPACE_ROOT?.trim() || "/draft-pr-workspaces",
    token,
    authorName: process.env.DRAFT_PR_GIT_AUTHOR_NAME?.trim() || "engineering-agent-workflows",
    authorEmail: process.env.DRAFT_PR_GIT_AUTHOR_EMAIL?.trim() || "engineering-agent-workflows@users.noreply.github.com",
    ...process.env.DRAFT_PR_GIT_CURL_RESOLVE ? { gitCurlResolve: process.env.DRAFT_PR_GIT_CURL_RESOLVE } : {}
  });
  const dependencies = {
    provider,
    workspace,
    policy,
    allowedRepository,
    serverUrl: process.env.GITHUB_SERVER_URL?.trim() || "https://github.com",
    apply,
    ...process.env.GITHUB_BOT_LOGIN ? { botLogin: process.env.GITHUB_BOT_LOGIN } : {}
  };
  const result = options.command === "prepare" ? await prepareDraftPr(
    options.repository,
    options.issueNumber,
    options.trigger,
    dependencies
  ) : options.command === "apply" ? await applyDraftPr(
    options.repository,
    options.issueNumber,
    JSON.parse(
      await readFile2(options.analysisFile, "utf8")
    ),
    dependencies
  ) : options.command === "fail" ? await failDraftPr(
    options.repository,
    options.issueNumber,
    options.message ?? "Draft PR Agent execution failed",
    dependencies
  ) : options.command === "prepare-review" ? await prepareReviewFix(
    options.repository,
    options.pullRequestNumber,
    options.reviewId,
    dependencies
  ) : options.command === "apply-review" ? await applyReviewFix(
    options.repository,
    options.pullRequestNumber,
    JSON.parse(
      await readFile2(options.analysisFile, "utf8")
    ),
    dependencies
  ) : options.command === "fail-review" ? await failReviewFix(
    options.repository,
    options.pullRequestNumber,
    options.reviewCursor ?? 0,
    options.iterations ?? 0,
    options.headSha ?? "",
    dependencies
  ) : options.command === "prepare-ci" ? await prepareCiFix(
    options.repository,
    options.pullRequestNumber,
    options.headSha ?? "",
    options.checkSuiteId ?? 0,
    dependencies
  ) : options.command === "apply-ci" ? await applyCiFix(
    options.repository,
    options.pullRequestNumber,
    JSON.parse(
      await readFile2(options.analysisFile, "utf8")
    ),
    dependencies
  ) : await failCiFix(
    options.repository,
    options.pullRequestNumber,
    options.checkSuiteId ?? 0,
    options.attempts ?? 0,
    options.headSha ?? "",
    dependencies
  );
  process.stdout.write(`${JSON.stringify(result, null, 2)}
`);
}
async function loadPolicy() {
  const embedded = process.env.WORKFLOW_POLICY_JSON?.trim();
  if (embedded) {
    try {
      return draftPrPolicySchema.parse(JSON.parse(embedded));
    } catch (error) {
      throw new Error(
        `failed to load embedded Draft PR policy: ${errorMessage(error)}`
      );
    }
  }
  return loadJsonFromCandidates(
    [
      fileURLToPath(new URL("../policy.json", import.meta.url)),
      path2.resolve("agents/draft-pr/policy.json")
    ],
    (value) => draftPrPolicySchema.parse(value),
    "failed to load Draft PR policy"
  );
}
function parseArguments(args) {
  const command = args.shift();
  if (command !== "prepare" && command !== "inspect-validation" && command !== "apply" && command !== "fail" && command !== "prepare-review" && command !== "apply-review" && command !== "fail-review" && command !== "prepare-ci" && command !== "apply-ci" && command !== "fail-ci") {
    throw new Error("invalid Draft PR tool command");
  }
  let repository = "";
  let issueNumber = 0;
  let pullRequestNumber = 0;
  let trigger = "";
  let analysisFile = "";
  let message = "";
  let reviewId = 0;
  let reviewCursor = 0;
  let iterations = 0;
  let headSha = "";
  let checkSuiteId = 0;
  let attempts = 0;
  let workspacePath = "";
  for (let index = 0; index < args.length; index += 1) {
    const argument = args[index];
    if (argument === "--repository") {
      repository = requiredArgumentValue(args, ++index, argument);
    } else if (argument === "--issue") {
      issueNumber = Number(requiredArgumentValue(args, ++index, argument));
    } else if (argument === "--pull-request") {
      pullRequestNumber = Number(
        requiredArgumentValue(args, ++index, argument)
      );
    } else if (argument === "--trigger") {
      trigger = requiredArgumentValue(args, ++index, argument);
    } else if (argument === "--analysis") {
      analysisFile = requiredArgumentValue(args, ++index, argument);
    } else if (argument === "--message") {
      message = requiredArgumentValue(args, ++index, argument);
    } else if (argument === "--review") {
      reviewId = Number(requiredArgumentValue(args, ++index, argument));
    } else if (argument === "--review-cursor") {
      reviewCursor = Number(requiredArgumentValue(args, ++index, argument));
    } else if (argument === "--iterations") {
      iterations = Number(requiredArgumentValue(args, ++index, argument));
    } else if (argument === "--head") {
      headSha = requiredArgumentValue(args, ++index, argument);
    } else if (argument === "--check-suite") {
      checkSuiteId = Number(requiredArgumentValue(args, ++index, argument));
    } else if (argument === "--attempts") {
      attempts = Number(requiredArgumentValue(args, ++index, argument));
    } else if (argument === "--workspace") {
      workspacePath = requiredArgumentValue(args, ++index, argument);
    } else {
      throw new Error(`unknown argument: ${argument}`);
    }
  }
  if (!isRepositorySlug(repository)) {
    throw new Error("--repository must use owner/repository format");
  }
  if (["prepare", "inspect-validation", "apply", "fail"].includes(command) && (!Number.isSafeInteger(issueNumber) || issueNumber <= 0)) {
    throw new Error("--issue must be a positive integer");
  }
  if ([
    "prepare-review",
    "apply-review",
    "fail-review",
    "prepare-ci",
    "apply-ci",
    "fail-ci"
  ].includes(command) && (!Number.isSafeInteger(pullRequestNumber) || pullRequestNumber <= 0)) {
    throw new Error("--pull-request must be a positive integer");
  }
  if (command === "prepare" && trigger !== "ready" && trigger !== "approved") {
    throw new Error("prepare requires --trigger ready or approved");
  }
  if (command === "inspect-validation" && !workspacePath) {
    throw new Error("inspect-validation requires --workspace");
  }
  if (command === "prepare-review" && (!Number.isSafeInteger(reviewId) || reviewId <= 0)) {
    throw new Error("prepare-review requires --review");
  }
  if ((command === "apply" || command === "apply-review" || command === "apply-ci") && !analysisFile) {
    throw new Error(`${command} requires --analysis`);
  }
  return {
    command,
    repository,
    ...issueNumber ? { issueNumber } : {},
    ...pullRequestNumber ? { pullRequestNumber } : {},
    ...trigger === "ready" || trigger === "approved" ? { trigger } : {},
    ...analysisFile ? { analysisFile } : {},
    ...message ? { message } : {},
    ...reviewId ? { reviewId } : {},
    ...reviewCursor ? { reviewCursor } : {},
    ...iterations ? { iterations } : {},
    ...headSha ? { headSha } : {},
    ...Number.isSafeInteger(checkSuiteId) && checkSuiteId > 0 ? { checkSuiteId } : {},
    ...Number.isSafeInteger(attempts) && attempts >= 0 ? { attempts } : {},
    ...workspacePath ? { workspacePath } : {}
  };
}
main().catch((error) => {
  process.stderr.write(`draft-pr failed: ${errorMessage(error)}
`);
  process.exitCode = 1;
});
